"use client"

// Bollard UI — connection-string-input · MIT licence · https://bollard-ui.vercel.app/components/connection-string-input

import * as React from "react"
import { Check, CircleAlert, CircleCheck, Copy, Database, Eye, EyeOff, Info, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { checkConnectionString, maskConnectionString, parseConnectionString, safeDecode, type ConnectionFix, type ConnectionIssue, type DbEnvironment } from "@/components/connection-string-input/connection-string"

export { checkConnectionString, cleanConnectionString, editDistance, encodePassword, maskConnectionString, parseConnectionString, safeDecode, strictHost, type ConnectionFix, type ConnectionIssue, type ConnectionIssueKind, type DbEnvironment, type DbFamily, type ParsedConnection } from "@/components/connection-string-input/connection-string"

export const CONNECTION_STRING_INPUT_MESSAGES = {
  label: "Database URL",
  placeholder: "postgresql://user:password@host:5432/database?sslmode=verify-full",
  readback: "What the driver connects to",
  user: "User",
  password: "Password",
  host: "Host",
  database: "Database",
  tls: "Encryption",
  none: "None",
  passwordRead: "{count} characters, hidden",
  noPassword: "None in the URL",
  show: "Show password",
  hide: "Hide password",
  copy: "Copy without password",
  copied: "Copied with the password masked",
  defaultDb: "Same as the user name",
  clean: "Looks right for {environment}.",
  toFix: "{count} to fix",
  toReview: "{count} to review",
  production: "production",
  staging: "staging",
  development: "development",
  "tls-verify-full": "TLS, certificate and host name checked",
  "tls-verify-ca": "TLS, certificate checked but not the host name",
  "tls-require": "TLS, certificate not checked",
  "tls-prefer": "Tries TLS, falls back to unencrypted",
  "tls-allow": "Unencrypted unless the server insists",
  "tls-disable": "Unencrypted",
  "tls-default": "Not set: libpq uses prefer (falls back to unencrypted)",
  "tls-system": "TLS, certificate and host name checked (sslrootcert=system)",
  "tls-on": "TLS",
  "tls-off": "Unencrypted",
  "pasted-wrapper": "Quotes, a KEY= prefix or line breaks came along with the paste. Drivers read them as part of the URL.",
  "not-a-url": "This isn't a connection URL. It should start with something like postgresql://.",
  jdbc: "That's a JDBC URL. Node, Python and Go drivers want it without jdbc:, and JDBC puts the user and password in ?user= and ?password=.",
  "scheme-typo": "{scheme}:// isn't a database scheme, so the driver refuses it. Did you mean {guess}://?",
  "unknown-scheme": "{scheme}:// isn't one this field knows, so only the password and host are checked.",
  "password-at": "The password has an @ that isn't encoded. Parsers that split at the first @ (libpq, psql) try to connect to “{host}”. Needs encoding: {chars}",
  "password-hash": "The password has a #, and URL parsers treat everything after # as a fragment, so the password is cut short. Needs encoding: {chars}",
  "password-ends-early": "The password has a {chars} that isn't encoded, so URL parsers end the host there and the connection fails.",
  "bad-percent": "The password has a % that isn't followed by two hex digits, so drivers fail to decode it (URIError: URI malformed).",
  "password-colon": "The password has a : that isn't encoded. Most drivers still read it right, but encode it as %3A so every one does.",
  "password-space": "The password has a space. Encode it so no driver trims or splits it.",
  "localhost-prod": "{host} in production points at the app's own server or container, not your database.",
  "no-host": "No host, so libpq connects through a local Unix socket instead of the network.",
  "bad-port": "Port “{port}” isn't a number.",
  "wrong-port": "Port {port} is {owner}'s default. Is this the right server?",
  "srv-port": "mongodb+srv:// URLs can't have a port; the driver looks the ports up in DNS and rejects this one.",
  "srv-hosts": "mongodb+srv:// takes exactly one host name (the DNS seed), so drivers reject these {count}. List several hosts with mongodb:// instead.",
  "rootcert-system-mode": "With sslrootcert=system, libpq only accepts sslmode=verify-full, so sslmode={mode} fails to connect.",
  "mongo-password-colon": "The password has a : that isn't encoded. MongoDB drivers reject a second colon in the user info, so encode it as %3A.",
  "no-database": "No database name, so Postgres connects to one named after the user ({user}).",
  "no-sslmode": "No sslmode, so libpq uses prefer: it falls back to an unencrypted connection and never checks the certificate.",
  "weak-sslmode": "sslmode={mode} in production can send the password and data unencrypted.",
  "bad-sslmode": "sslmode={mode} isn't valid, so libpq refuses to connect. It takes disable, allow, prefer, require, verify-ca or verify-full.",
  "unknown-param": "libpq refuses ?{key}= as an invalid parameter (other drivers may ignore it). Parameter names are case-sensitive, and only ssl=true is accepted as a JDBC alias.",
  "redis-plain": "redis:// is unencrypted. Managed Redis outside your network needs rediss://.",
  "mongo-no-tls": "This MongoDB URL connects without TLS. mongodb:// needs tls=true; mongodb+srv:// turns TLS on unless tls=false.",
  "fix-pasted-wrapper": "Clean it",
  "fix-jdbc": "Remove jdbc:",
  "fix-encode": "Encode the password",
  "fix-drop-port": "Remove the port",
  "fix-use": "Use {value}",
}
export type ConnectionStringInputMessages = typeof CONNECTION_STRING_INPUT_MESSAGES

const fill = (text: string, values: Record<string, string | number>) => text.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))
const tones = { error: "text-red-700 dark:text-red-400", warning: "text-amber-700 dark:text-amber-400", info: "text-muted-foreground" }
const icons = { error: CircleAlert, warning: TriangleAlert, info: Info }
const fixClass = (error: boolean) =>
  cn(
    "inline-flex min-h-6 items-center rounded-md border px-2 font-medium transition-colors outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50",
    error ? "border-red-500/40 text-red-800 hover:bg-red-500/10 dark:text-red-200" : "border-amber-500/40 text-amber-900 hover:bg-amber-500/10 dark:text-amber-200",
  )
const iconButton = "grid size-6 shrink-0 place-items-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"

function useSettled(text: string, delay = 900) {
  const [settled, setSettled] = React.useState(text)
  React.useEffect(() => {
    const timer = setTimeout(() => setSettled(text), delay)
    return () => clearTimeout(timer)
  }, [text, delay])
  return settled
}

export interface ConnectionStringInputProps extends Omit<React.ComponentProps<"input">, "value" | "defaultValue" | "onChange"> {
  /** Controlled connection URL. */
  value?: string
  /** Initial connection URL when uncontrolled. */
  defaultValue?: string
  /** Called with the text on every edit or fix. */
  onValueChange?: (value: string) => void
  /** Where this URL will be used. Production turns localhost and missing TLS into problems. */
  environment?: DbEnvironment
  /** Visible label; shorthand for `messages.label`. */
  label?: string
  /** Every visible string. `{host}`, `{chars}`, `{mode}` and the other placeholders are filled in. */
  messages?: Partial<ConnectionStringInputMessages>
  /** Form field name. The real (unmasked) URL is submitted through a hidden input, since the visible one is masked when blurred. */
  name?: string
}

/**
 * A database URL field that masks the password whenever it isn't being
 * edited and catches what breaks or weakens the connection: an unencoded
 * @, #, / or % in the password (with the host a strict parser would really
 * try), localhost in production, a missing or invalid sslmode, a port that
 * belongs to another database, and quotes or KEY= dragged in from a .env file.
 */
export function ConnectionStringInput({ value, defaultValue = "", onValueChange, environment = "production", label, messages, id, className, onFocus, onBlur, ref, name, form, "aria-describedby": describedBy, ...props }: ConnectionStringInputProps) {
  const t = { ...CONNECTION_STRING_INPUT_MESSAGES, ...messages, ...(label !== undefined && { label }) }
  const [inner, setInner] = React.useState(defaultValue)
  const text = String(value ?? inner ?? "")
  const [editing, setEditing] = React.useState(false)
  const [revealed, setRevealed] = React.useState(false)
  const [copied, setCopied] = React.useState(false)
  const input = React.useRef<HTMLInputElement>(null)
  const list = React.useRef<HTMLUListElement>(null)
  const refocus = React.useRef<number | null>(null)
  const autoId = React.useId()
  const inputId = id ?? autoId
  React.useImperativeHandle(ref, () => input.current as HTMLInputElement)

  const update = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }
  const issues = React.useMemo(() => checkConnectionString(text, environment), [text, environment])
  const parsed = React.useMemo(() => parseConnectionString(text), [text])
  const errors = issues.filter((issue) => issue.severity === "error").length
  const counted = issues.filter((issue) => issue.severity !== "info").length
  const summary = !text.trim() ? "" : counted ? [errors && fill(t.toFix, { count: errors }), counted - errors && fill(t.toReview, { count: counted - errors })].filter(Boolean).join(" · ") : fill(t.clean, { environment: t[environment] })
  const announced = useSettled(summary)
  const shown = editing || revealed ? text : maskConnectionString(text)

  React.useEffect(() => {
    if (refocus.current === null) return
    const buttons = list.current?.querySelectorAll<HTMLButtonElement>("button[data-fix]") ?? []
    ;(buttons[Math.min(refocus.current, buttons.length - 1)] ?? input.current)?.focus()
    refocus.current = null
  }, [text])
  React.useEffect(() => {
    if (!copied) return
    const timer = setTimeout(() => setCopied(false), 2000)
    return () => clearTimeout(timer)
  }, [copied])

  const fix = (next: ConnectionFix, button: HTMLElement) => {
    refocus.current = [...(list.current?.querySelectorAll("button[data-fix]") ?? [])].indexOf(button)
    update(next.next)
  }
  const copyMasked = async () => {
    try {
      await navigator.clipboard.writeText(maskConnectionString(text))
      setCopied(true)
    } catch {
      setCopied(false)
    }
  }
  const message = (issue: ConnectionIssue) => fill(t[issue.kind], issue.detail)

  const param = (name: string) => parsed?.params.find(([key]) => key.toLowerCase() === name)?.[1]
  const sslmode = param("sslmode")
  const mongoOff = param("tls") === "false" || param("ssl") === "false"
  const tls = !parsed
    ? ""
    : parsed.family === "postgres"
      ? sslmode && `tls-${sslmode}` in t
        ? t[`tls-${sslmode}` as keyof ConnectionStringInputMessages]
        : param("sslrootcert") === "system"
          ? t["tls-system"]
          : param("ssl") === "true"
            ? t["tls-require"]
            : t["tls-default"]
      : parsed.scheme === "rediss" || (parsed.scheme === "mongodb+srv" && !mongoOff) || param("tls") === "true" || param("ssl") === "true"
        ? t["tls-on"]
        : parsed.family === "redis" || parsed.family === "mongodb"
          ? t["tls-off"]
          : ""
  const password = parsed?.hasPassword ? (safeDecode(parsed.rawPassword) ?? parsed.rawPassword) : ""
  const rows: [string, React.ReactNode][] = parsed
    ? [
        [t.user, safeDecode(parsed.user) ?? parsed.user],
        [t.password, parsed.hasPassword ? (revealed ? password : fill(t.passwordRead, { count: [...password].length })) : t.noPassword],
        [t.host, parsed.hosts.map(({ host, port }) => (port ? `${host}:${port}` : host)).join(", ") || t.none],
        [t.database, parsed.database ? (safeDecode(parsed.database) ?? parsed.database) : parsed.family === "postgres" ? t.defaultDb : t.none],
        ...(tls ? ([[t.tls, tls]] as [string, string][]) : []),
      ]
    : []

  return (
    <div data-slot="connection-string-input" className={cn("grid w-full max-w-xl min-w-0 grid-cols-[minmax(0,1fr)] gap-1.5 text-sm", className)}>
      <label htmlFor={inputId} className="flex w-fit items-center gap-1.5 font-medium">
        <Database aria-hidden className="size-4 text-muted-foreground" />
        {t.label}
      </label>
      <input
        ref={input}
        id={inputId}
        value={shown}
        onChange={(event) => update(event.target.value)}
        onFocus={(event) => {
          const el = event.currentTarget
          const maskFrom = parsed?.passwordRange ? Math.max(0, text.indexOf(parsed.clean)) + parsed.passwordRange[0] : Infinity
          const caret = el.selectionStart ?? el.value.length
          const all = el.value !== "" && el.selectionStart === 0 && el.selectionEnd === el.value.length
          // Swap in the real text right away (not on the next render), keeping a tab-in "select all" so a paste replaces
          // instead of appending. A caret before the password keeps its spot; one inside or after it goes to the end.
          if (el.value !== text) {
            el.value = text
            if (all) el.select()
            else if (caret <= maskFrom) el.setSelectionRange(caret, caret)
          }
          setEditing(true)
          onFocus?.(event)
        }}
        onBlur={(event) => {
          setEditing(false)
          onBlur?.(event)
        }}
        placeholder={t.placeholder}
        spellCheck={false}
        autoCapitalize="none"
        autoCorrect="off"
        autoComplete="off"
        data-1p-ignore=""
        data-lpignore="true"
        aria-invalid={errors > 0 || undefined}
        aria-describedby={[describedBy, `${inputId}-status`].filter(Boolean).join(" ")}
        className="h-9 w-full min-w-0 rounded-md border bg-transparent px-3 font-mono text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:font-sans placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive md:text-xs dark:bg-input/30"
        {...props}
      />
      {/* The visible field shows a masked password when blurred, so forms get the real value from here. */}
      {name && <input type="hidden" name={name} form={form} value={text} />}
      <span role="status" className="sr-only">
        {announced}
      </span>
      {parsed && (
        <section aria-labelledby={`${inputId}-readback`} className="mt-1.5 grid gap-1.5 rounded-md border bg-muted/40 p-3 text-xs">
          <div className="flex items-center justify-between gap-2">
            <h3 id={`${inputId}-readback`} className="font-medium text-muted-foreground">
              {t.readback}
            </h3>
            <button type="button" onClick={copyMasked} className="inline-flex h-6 items-center gap-1 rounded-md px-1.5 text-muted-foreground transition-colors hover:bg-accent hover:text-foreground outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50">
              {copied ? <Check aria-hidden className="size-3.5" /> : <Copy aria-hidden className="size-3.5" />}
              <span aria-live="polite">{copied ? t.copied : t.copy}</span>
            </button>
          </div>
          <dl className="grid grid-cols-[minmax(0,5.5rem)_minmax(0,1fr)] gap-x-2 gap-y-1">
            {rows.map(([name, read]) => (
              <React.Fragment key={name}>
                <dt className="text-muted-foreground">{name}</dt>
                <dd className={cn("flex min-w-0 items-center gap-1", name === t.tls || (name === t.password && !revealed) || (name === t.database && !parsed.database) ? "" : "font-mono break-all")}>
                  <span className="min-w-0">{read}</span>
                  {name === t.password && parsed.hasPassword && (
                    <button type="button" onClick={() => setRevealed((open) => !open)} aria-pressed={revealed} aria-label={revealed ? t.hide : t.show} title={revealed ? t.hide : t.show} className={iconButton}>
                      {revealed ? <EyeOff aria-hidden className="size-3.5" /> : <Eye aria-hidden className="size-3.5" />}
                    </button>
                  )}
                </dd>
              </React.Fragment>
            ))}
          </dl>
        </section>
      )}
      <div id={`${inputId}-status`} className="mt-1.5 grid gap-1.5 text-xs">
        {summary && (
          <span className={cn("flex items-center gap-1.5", counted ? "text-muted-foreground" : "text-emerald-700 dark:text-emerald-400")}>
            {counted ? <TriangleAlert aria-hidden className={cn("size-3.5", errors ? "text-red-600 dark:text-red-400" : "text-amber-600 dark:text-amber-400")} /> : <CircleCheck aria-hidden className="size-3.5" />}
            {summary}
          </span>
        )}
        {issues.length > 0 && (
          <ul ref={list} className="grid gap-1.5">
            {issues.map((issue, index) => {
              const Icon = icons[issue.severity]
              return (
                <li key={`${issue.kind}-${index}`} className={cn("flex gap-1.5", tones[issue.severity])}>
                  <span className="flex h-6 shrink-0 items-center">
                    <Icon aria-hidden className="size-3.5" />
                  </span>
                  <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
                    <span className="py-1 [overflow-wrap:anywhere]">{message(issue)}</span>
                    {issue.fixes.map((next) => (
                      <button key={next.next} type="button" data-fix="" onClick={(event) => fix(next, event.currentTarget)} className={fixClass(issue.severity === "error")}>
                        {fill(t[next.label as keyof ConnectionStringInputMessages] ?? next.label, next.detail ?? {})}
                      </button>
                    ))}
                  </span>
                </li>
              )
            })}
          </ul>
        )}
      </div>
    </div>
  )
}

// Bollard UI — connection-string-input · MIT licence · https://bollard-ui.vercel.app/components/connection-string-input

/**
 * Database connection URLs, split the way drivers split them and checked for
 * the mistakes that break or weaken a connection. Sources: libpq connection
 * URIs and sslmode (https://www.postgresql.org/docs/current/libpq-connect.html),
 * the MongoDB connection-string and SRV specs
 * (https://github.com/mongodb/specifications/tree/master/source),
 * RFC 3986 percent-encoding, and the WHATWG URL parser most JS drivers use.
 */

export type DbEnvironment = "production" | "staging" | "development"
export type DbFamily = "postgres" | "mysql" | "mongodb" | "redis"

export interface ParsedConnection {
  /** The text after cleaning (quotes, KEY= prefix, BOM, line breaks removed). */
  clean: string
  scheme: string
  family?: DbFamily
  user: string
  /** Password exactly as written in the URL (still percent-encoded). */
  rawPassword: string
  hasPassword: boolean
  hosts: { host: string; port: string }[]
  database: string
  params: [string, string][]
  /** Index range of the raw password in `clean`, for masking. */
  passwordRange?: [number, number]
  /** Index in `clean` where the path, query or fragment after the host starts. */
  tailStart: number
}

export type ConnectionIssueKind =
  | "pasted-wrapper"
  | "not-a-url"
  | "jdbc"
  | "scheme-typo"
  | "unknown-scheme"
  | "password-at"
  | "password-ends-early"
  | "password-hash"
  | "password-colon"
  | "password-space"
  | "bad-percent"
  | "localhost-prod"
  | "no-host"
  | "bad-port"
  | "wrong-port"
  | "srv-port"
  | "srv-hosts"
  | "rootcert-system-mode"
  | "mongo-password-colon"
  | "no-database"
  | "no-sslmode"
  | "weak-sslmode"
  | "bad-sslmode"
  | "unknown-param"
  | "redis-plain"
  | "mongo-no-tls"
export interface ConnectionFix {
  /** Message key for the button label. */
  label: string
  /** Values filled into the label. */
  detail?: Record<string, string>
  /** The whole connection string after the fix. */
  next: string
}
export interface ConnectionIssue {
  kind: ConnectionIssueKind
  severity: "error" | "warning" | "info"
  detail: Record<string, string>
  fixes: ConnectionFix[]
}

const SCHEMES: Record<string, DbFamily> = { postgres: "postgres", postgresql: "postgres", mysql: "mysql", mariadb: "mysql", mongodb: "mongodb", "mongodb+srv": "mongodb", redis: "redis", rediss: "redis" }
const DEFAULT_PORT: Record<DbFamily, string> = { postgres: "5432", mysql: "3306", mongodb: "27017", redis: "6379" }
const PORT_OWNER: Record<string, string> = { "5432": "PostgreSQL", "3306": "MySQL", "27017": "MongoDB", "6379": "Redis", "1433": "SQL Server" }
const LOCAL_HOSTS = /^(localhost|127(?:\.\d{1,3}){3}|\[?::1\]?|0\.0\.0\.0|host\.docker\.internal)$/i
const SSLMODES = ["disable", "allow", "prefer", "require", "verify-ca", "verify-full"]
// libpq rejects any URI parameter that isn't one of its key words (case-sensitive). Only ssl=true is translated (to
// sslmode=require) for JDBC compatibility; ssl=false or ssl=1 fail with "invalid URI query parameter".
const LIBPQ_KEYWORDS = ["host", "hostaddr", "port", "dbname", "user", "password", "passfile", "require_auth", "channel_binding", "connect_timeout", "client_encoding", "options", "application_name", "fallback_application_name", "keepalives", "keepalives_idle", "keepalives_interval", "keepalives_count", "tcp_user_timeout", "replication", "gssencmode", "sslmode", "requiressl", "sslnegotiation", "sslcompression", "sslcert", "sslkey", "sslkeylogfile", "sslpassword", "sslcertmode", "sslrootcert", "sslcrl", "sslcrldir", "sslsni", "requirepeer", "ssl_min_protocol_version", "ssl_max_protocol_version", "min_protocol_version", "max_protocol_version", "krbsrvname", "gsslib", "gssdelegation", "service", "target_session_attrs", "load_balance_hosts"]
// Parameters common drivers (node-postgres, Prisma, psycopg pools) accept on top of libpq's own.
const DRIVER_EXTRAS = ["schema", "connection_limit", "pool_timeout", "pgbouncer", "statement_cache_size", "socket_timeout", "connect_timeout", "sslaccept", "uselibpqcompat"]

/** Damerau-Levenshtein distance, capped for speed. */
export function editDistance(a: string, b: string): number {
  if (Math.abs(a.length - b.length) > 2) return 3
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)])
  for (let j = 1; j <= b.length; j++) d[0][j] = j
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost)
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1)
    }
  return d[a.length][b.length]
}
const nearest = (word: string, list: string[], max = 2) => {
  let best: string | undefined
  let score = max + 1
  for (const candidate of list) {
    const distance = editDistance(word.toLowerCase(), candidate)
    if (distance < score) [best, score] = [candidate, distance]
  }
  return score <= max ? best : undefined
}

/** Removes what a copy from a .env file or a shell brings along: KEY=, quotes, BOM, CR/LF and spaces. */
export function cleanConnectionString(raw: string): string {
  return String(raw ?? "")
    .replace(/^\uFEFF/, "")
    .replace(/[\r\n]+/g, "")
    .trim()
    .replace(/^(?:export\s+)?[A-Z][A-Z0-9_]*\s*=\s*/, "")
    .replace(/^(["'`])(.*)\1;?$/, "$2")
    .trim()
}

/** Percent-encodes what a password needs encoded, leaving existing %XX escapes alone. */
export function encodePassword(raw: string): string {
  return raw.replace(/%(?![0-9A-Fa-f]{2})|[^A-Za-z0-9\-._~!$&'()*+,;=%]/g, (char) => encodeURIComponent(char))
}

/** Decodes a percent-encoded part, or returns null when it would throw (a stray %). */
export function safeDecode(part: string): string | null {
  try {
    return decodeURIComponent(part)
  } catch {
    return null
  }
}

/**
 * Splits a connection URL the forgiving way, taking the host after the last
 * `@`, so a password with an unencoded @, / or # still comes out whole and
 * can be re-encoded in one tap.
 */
export function parseConnectionString(raw: string): ParsedConnection | null {
  const clean = cleanConnectionString(raw)
  const scheme = /^([a-z][a-z0-9+.-]*):\/\//i.exec(clean)
  if (!scheme) return null
  const start = scheme[0].length
  const rest = clean.slice(start)
  let at = rest.lastIndexOf("@")
  // An @ inside the query string (?application_name=a@b) isn't the credentials separator: step back to the one before it.
  while (at > 0) {
    const previous = rest.lastIndexOf("@", at - 1)
    if (previous < 0 || !/\?[^@]*=/.test(rest.slice(previous + 1, at))) break
    at = previous
  }
  const userinfo = at >= 0 ? rest.slice(0, at) : ""
  const afterAt = at >= 0 ? rest.slice(at + 1) : rest
  const hostEnd = afterAt.search(/[/?#]/)
  const hostPart = hostEnd < 0 ? afterAt : afterAt.slice(0, hostEnd)
  const tail = hostEnd < 0 ? "" : afterAt.slice(hostEnd)
  const colon = userinfo.indexOf(":")
  const user = colon >= 0 ? userinfo.slice(0, colon) : userinfo
  const rawPassword = colon >= 0 ? userinfo.slice(colon + 1) : ""
  const pathMatch = /^\/([^?#]*)/.exec(tail)
  const query = /\?([^#]*)/.exec(tail)?.[1] ?? ""
  const hosts = hostPart
    ? hostPart.split(",").map((entry) => {
        const ipv6 = /^(\[[^\]]*\])(?::(.*))?$/.exec(entry)
        if (ipv6) return { host: ipv6[1], port: ipv6[2] ?? "" }
        const index = entry.lastIndexOf(":")
        return index >= 0 ? { host: entry.slice(0, index), port: entry.slice(index + 1) } : { host: entry, port: "" }
      })
    : []
  const params = query
    ? query.split("&").filter(Boolean).map((pair): [string, string] => {
        const index = pair.indexOf("=")
        return index >= 0 ? [pair.slice(0, index), pair.slice(index + 1)] : [pair, ""]
      })
    : []
  const passwordStart = start + colon + 1
  return {
    clean,
    scheme: scheme[1].toLowerCase(),
    family: SCHEMES[scheme[1].toLowerCase()],
    user,
    rawPassword,
    hasPassword: colon >= 0,
    hosts,
    database: pathMatch?.[1] ?? "",
    params,
    passwordRange: colon >= 0 ? [passwordStart, passwordStart + rawPassword.length] : undefined,
    tailStart: start + (at >= 0 ? at + 1 : 0) + hostPart.length,
  }
}

/** The connection string with the password replaced by a fixed-length mask, safe for logs and tickets. */
export function maskConnectionString(raw: string, mask = "••••••••"): string {
  const parsed = parseConnectionString(raw)
  const text = String(raw ?? "")
  if (!parsed?.passwordRange || !parsed.rawPassword) return text
  // Mask inside the text as typed, so quotes or a KEY= prefix stay visible until they're fixed.
  const offset = Math.max(0, text.indexOf(parsed.clean))
  const [from, to] = parsed.passwordRange
  return text.slice(0, offset + from) + mask + text.slice(offset + to)
}

/** What a strict parser that stops at the first @ or / (libpq, psql) would take as the host. */
export function strictHost(clean: string): string {
  const rest = clean.replace(/^[a-z][a-z0-9+.-]*:\/\//i, "")
  const stop = rest.search(/[@/]/)
  const afterUser = stop >= 0 && rest[stop] === "@" ? rest.slice(stop + 1) : rest
  // libpq ends the host at : / ? or , (fe-connect.c); # is not special to it. An IPv6 host runs to its ].
  if (afterUser.startsWith("[")) return afterUser.slice(0, afterUser.indexOf("]") + 1 || undefined)
  return afterUser.split(/[:/?,]/)[0]
}

function withPassword(parsed: ParsedConnection, password: string) {
  const [from, to] = parsed.passwordRange ?? [0, 0]
  return parsed.clean.slice(0, from) + password + parsed.clean.slice(to)
}
function setParam(parsed: ParsedConnection, key: string, value: string) {
  const head = parsed.clean.slice(0, parsed.tailStart)
  const [tail, hash] = parsed.clean.slice(parsed.tailStart).split(/#(.*)/s)
  // MongoDB wants the slash before the options (mongodb://host/?tls=true).
  const base = parsed.family === "mongodb" && !tail.startsWith("/") ? `/${tail}` : tail
  const pattern = new RegExp(`([?&])${key}=[^&]*`)
  const next = pattern.test(base) ? base.replace(pattern, `$1${key}=${value}`) : `${base}${base.includes("?") ? "&" : "?"}${key}=${value}`
  return head + next + (hash !== undefined ? `#${hash}` : "")
}

/** Checks a connection URL for the environment it's being saved to and returns every problem, most serious first. */
export function checkConnectionString(raw: string, environment: DbEnvironment = "production"): ConnectionIssue[] {
  const text = String(raw ?? "")
  if (!text.trim()) return []
  const issues: ConnectionIssue[] = []
  const clean = cleanConnectionString(text)
  if (clean !== text.trim()) issues.push({ kind: "pasted-wrapper", severity: "warning", detail: {}, fixes: [{ label: "fix-pasted-wrapper", next: clean }] })
  if (/^jdbc:/i.test(clean)) {
    issues.push({ kind: "jdbc", severity: "warning", detail: {}, fixes: [{ label: "fix-jdbc", next: clean.replace(/^jdbc:/i, "") }] })
    return issues
  }
  const parsed = parseConnectionString(clean)
  if (!parsed) {
    issues.push({ kind: "not-a-url", severity: "error", detail: {}, fixes: [] })
    return issues
  }
  if (!parsed.family) {
    const guess = nearest(parsed.scheme, Object.keys(SCHEMES))
    issues.push(guess ? { kind: "scheme-typo", severity: "error", detail: { scheme: parsed.scheme, guess }, fixes: [{ label: "fix-use", detail: { value: `${guess}://` }, next: clean.replace(/^[^:]+/, guess) }] } : { kind: "unknown-scheme", severity: "info", detail: { scheme: parsed.scheme }, fixes: [] })
  }
  const family = parsed.family
  const prod = environment === "production"
  const param = (key: string) => parsed.params.find(([name]) => name.toLowerCase() === key)?.[1]

  if (parsed.hasPassword) {
    const password = parsed.rawPassword
    const encoded = encodePassword(password)
    const fix = [{ label: "fix-encode", next: withPassword(parsed, encoded) }]
    const strict = strictHost(clean)
    // One line per password, naming its worst character and listing every character that needs encoding.
    const chars = [...new Set(password.replace(/%[0-9A-Fa-f]{2}/g, "").match(/[^A-Za-z0-9\-._~!$&'()*+,;=]/g) ?? [])].map((char) => (char === " " ? "space" : char)).join(" ")
    const detail = { host: strict, chars }
    const worst: [ConnectionIssueKind, boolean][] = [["password-at", password.includes("@")], ["password-hash", password.includes("#")], ["password-ends-early", /[/?]/.test(password)], ["bad-percent", /%(?![0-9A-Fa-f]{2})/.test(password)], ["password-colon", password.includes(":")], ["password-space", /\s/.test(password)]]
    const found = worst.find(([, hit]) => hit)
    // The MongoDB connection-string spec makes drivers throw on a second unencoded colon in the userinfo.
    if (found?.[0] === "password-colon" && family === "mongodb") issues.push({ kind: "mongo-password-colon", severity: "error", detail, fixes: fix })
    else if (found) issues.push({ kind: found[0], severity: ["password-colon", "password-space"].includes(found[0]) ? "warning" : "error", detail, fixes: fix })
  }

  const hosts = parsed.hosts.filter((entry) => entry.host)
  if (!hosts.length && !parsed.params.some(([key]) => key === "host")) issues.push({ kind: "no-host", severity: "warning", detail: {}, fixes: [] })
  for (const { host, port } of parsed.hosts) {
    if (prod && LOCAL_HOSTS.test(host)) issues.push({ kind: "localhost-prod", severity: "error", detail: { host }, fixes: [] })
    if (port && !/^\d{1,5}$/.test(port)) issues.push({ kind: "bad-port", severity: "error", detail: { port }, fixes: [] })
    else if (port && parsed.scheme === "mongodb+srv") issues.push({ kind: "srv-port", severity: "error", detail: { port }, fixes: [{ label: "fix-drop-port", next: clean.replace(`${host}:${port}`, host) }] })
    else if (port && family && PORT_OWNER[port] && port !== DEFAULT_PORT[family] && !(family === "postgres" && port === "6543")) {
      issues.push({ kind: "wrong-port", severity: "warning", detail: { port, owner: PORT_OWNER[port] }, fixes: [{ label: "fix-use", detail: { value: `:${DEFAULT_PORT[family]}` }, next: clean.replace(`${host}:${port}`, `${host}:${DEFAULT_PORT[family]}`) }] })
    }
  }
  if (family === "postgres" && !parsed.database && !parsed.params.some(([key]) => key === "dbname")) issues.push({ kind: "no-database", severity: "info", detail: { user: safeDecode(parsed.user) ?? parsed.user }, fixes: [] })

  const remote = hosts.length > 0 && hosts.every(({ host }) => !LOCAL_HOSTS.test(host))
  if (parsed.scheme === "mongodb+srv" && hosts.length > 1) issues.push({ kind: "srv-hosts", severity: "error", detail: { count: String(hosts.length) }, fixes: [] })
  if (family === "postgres") {
    for (const [key] of parsed.params) {
      if (LIBPQ_KEYWORDS.includes(key) || DRIVER_EXTRAS.includes(key) || (key === "ssl" && param("ssl") === "true")) continue
      const guess = key === "ssl" ? undefined : nearest(key, LIBPQ_KEYWORDS)
      issues.push({ kind: "unknown-param", severity: "warning", detail: { key, guess: guess ?? "" }, fixes: guess ? [{ label: "fix-use", detail: { value: guess }, next: clean.replace(new RegExp(`([?&])${key}=`), `$1${guess}=`) }] : [] })
    }
    const mode = param("sslmode")
    const systemRoots = param("sslrootcert") === "system"
    if (mode !== undefined && !SSLMODES.includes(mode)) {
      const guess = nearest(mode.replace(/_/g, "-"), SSLMODES, 3) ?? "require"
      issues.push({ kind: "bad-sslmode", severity: "error", detail: { mode, guess }, fixes: [{ label: "fix-use", detail: { value: `sslmode=${guess}` }, next: setParam(parsed, "sslmode", guess) }] })
    } else if (systemRoots && mode !== undefined && mode !== "verify-full") {
      // libpq: "When using sslrootcert=system, the default sslmode is changed to verify-full, and any weaker setting will result in an error."
      issues.push({ kind: "rootcert-system-mode", severity: "error", detail: { mode }, fixes: [{ label: "fix-use", detail: { value: "sslmode=verify-full" }, next: setParam(parsed, "sslmode", "verify-full") }] })
    } else if (prod && remote && mode === undefined && param("ssl") === undefined && !systemRoots) {
      issues.push({ kind: "no-sslmode", severity: "warning", detail: {}, fixes: [{ label: "fix-use", detail: { value: "sslmode=verify-full" }, next: setParam(parsed, "sslmode", "verify-full") }, { label: "fix-use", detail: { value: "sslmode=require" }, next: setParam(parsed, "sslmode", "require") }] })
    } else if (prod && remote && mode && ["disable", "allow", "prefer"].includes(mode)) {
      issues.push({ kind: "weak-sslmode", severity: mode === "disable" ? "error" : "warning", detail: { mode }, fixes: [{ label: "fix-use", detail: { value: "sslmode=verify-full" }, next: setParam(parsed, "sslmode", "verify-full") }] })
    }
  }
  if (family === "redis" && parsed.scheme === "redis" && prod && remote) issues.push({ kind: "redis-plain", severity: "warning", detail: {}, fixes: [{ label: "fix-use", detail: { value: "rediss://" }, next: clean.replace(/^redis:/i, "rediss:") }] })
  // mongodb:// is plaintext unless tls/ssl=true; mongodb+srv:// turns TLS on implicitly unless tls/ssl=false.
  const mongoTls = parsed.scheme === "mongodb+srv" ? param("tls") !== "false" && param("ssl") !== "false" : param("tls") === "true" || param("ssl") === "true"
  if (family === "mongodb" && prod && remote && !mongoTls) issues.push({ kind: "mongo-no-tls", severity: "warning", detail: {}, fixes: [{ label: "fix-use", detail: { value: "tls=true" }, next: setParam(parsed, param("ssl") !== undefined && param("tls") === undefined ? "ssl" : "tls", "true") }] })

  const order = { error: 0, warning: 1, info: 2 }
  return issues.sort((a, b) => order[a.severity] - order[b.severity])
}
